const rawText = $input.first().json?.body?.message?.text;

let parsed;
try {
  parsed = typeof rawText === "string" ? JSON.parse(rawText) : rawText;
} catch (e) {
  throw new Error(`JSON.parse failed: ${e.message} | Raw value: ${String(rawText).substring(0, 200)}`);
}

return [{ json: { message: parsed?.text ?? "" } }];

